class PaymentMethod:
    """
    FFI-compatible PaymentMethod
"""
    def __init__(self):
        raise RuntimeError("PaymentMethod cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class BOLT11:
        """
        Bolt11 payment type
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "PaymentMethod.BOLT11()".format()
        def __eq__(self, other):
            if not other.is_BOLT11():
                return False
            return True

    @dataclass
    class BOLT12:
        """
        Bolt12 payment type
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "PaymentMethod.BOLT12()".format()
        def __eq__(self, other):
            if not other.is_BOLT12():
                return False
            return True

    @dataclass
    class ONCHAIN:
        """
        Onchain Bitcoin payment type
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "PaymentMethod.ONCHAIN()".format()
        def __eq__(self, other):
            if not other.is_ONCHAIN():
                return False
            return True

    @dataclass
    class CUSTOM:
        """
        Custom payment type
"""
        
        def __init__(self, method:str):
            self.method = method
            
            
            pass

    
            
            
    
        def __str__(self):
            return "PaymentMethod.CUSTOM(method={})".format(self.method)
        def __eq__(self, other):
            if not other.is_CUSTOM():
                return False
            if self.method != other.method:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_BOLT11(self) -> bool:
        return isinstance(self, PaymentMethod.BOLT11)
    def is_bolt11(self) -> bool:
        return isinstance(self, PaymentMethod.BOLT11)
    def is_BOLT12(self) -> bool:
        return isinstance(self, PaymentMethod.BOLT12)
    def is_bolt12(self) -> bool:
        return isinstance(self, PaymentMethod.BOLT12)
    def is_ONCHAIN(self) -> bool:
        return isinstance(self, PaymentMethod.ONCHAIN)
    def is_onchain(self) -> bool:
        return isinstance(self, PaymentMethod.ONCHAIN)
    def is_CUSTOM(self) -> bool:
        return isinstance(self, PaymentMethod.CUSTOM)
    def is_custom(self) -> bool:
        return isinstance(self, PaymentMethod.CUSTOM)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
PaymentMethod.BOLT11 = type("PaymentMethod.BOLT11", (PaymentMethod.BOLT11, PaymentMethod,), {})  # type: ignore
PaymentMethod.BOLT12 = type("PaymentMethod.BOLT12", (PaymentMethod.BOLT12, PaymentMethod,), {})  # type: ignore
PaymentMethod.ONCHAIN = type("PaymentMethod.ONCHAIN", (PaymentMethod.ONCHAIN, PaymentMethod,), {})  # type: ignore
PaymentMethod.CUSTOM = type("PaymentMethod.CUSTOM", (PaymentMethod.CUSTOM, PaymentMethod,), {})  # type: ignore




class _UniffiFfiConverterTypePaymentMethod(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return PaymentMethod.BOLT11(
            )
        if variant == 2:
            return PaymentMethod.BOLT12(
            )
        if variant == 3:
            return PaymentMethod.ONCHAIN(
            )
        if variant == 4:
            return PaymentMethod.CUSTOM(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_BOLT11():
            return
        if value.is_BOLT12():
            return
        if value.is_ONCHAIN():
            return
        if value.is_CUSTOM():
            _UniffiFfiConverterString.check_lower(value.method)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_BOLT11():
            buf.write_i32(1)
        if value.is_BOLT12():
            buf.write_i32(2)
        if value.is_ONCHAIN():
            buf.write_i32(3)
        if value.is_CUSTOM():
            buf.write_i32(4)
            _UniffiFfiConverterString.write(value.method, buf)



