class Witness:
    """
    FFI-compatible Witness
"""
    def __init__(self):
        raise RuntimeError("Witness cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class P2PK:
        """
        P2PK Witness
"""
        
        def __init__(self, signatures:typing.List[str]):
            self.signatures = signatures
            
            """
        Signatures
"""
        
            pass

    
            
            
    
        def __str__(self):
            return "Witness.P2PK(signatures={})".format(self.signatures)
        def __eq__(self, other):
            if not other.is_P2PK():
                return False
            if self.signatures != other.signatures:
                return False
            return True

    @dataclass
    class HTLC:
        """
        HTLC Witness
"""
        
        def __init__(self, preimage:str, signatures:typing.Optional[typing.List[str]]):
            self.preimage = preimage
            
            """
        Preimage
"""
        
            self.signatures = signatures
            
            """
        Optional signatures
"""
        
            pass

    
            
            
    
        def __str__(self):
            return "Witness.HTLC(preimage={}, signatures={})".format(self.preimage, self.signatures)
        def __eq__(self, other):
            if not other.is_HTLC():
                return False
            if self.preimage != other.preimage:
                return False
            if self.signatures != other.signatures:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_P2PK(self) -> bool:
        return isinstance(self, Witness.P2PK)
    def is_p2pk(self) -> bool:
        return isinstance(self, Witness.P2PK)
    def is_HTLC(self) -> bool:
        return isinstance(self, Witness.HTLC)
    def is_htlc(self) -> bool:
        return isinstance(self, Witness.HTLC)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
Witness.P2PK = type("Witness.P2PK", (Witness.P2PK, Witness,), {})  # type: ignore
Witness.HTLC = type("Witness.HTLC", (Witness.HTLC, Witness,), {})  # type: ignore




class _UniffiFfiConverterTypeWitness(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Witness.P2PK(
                _UniffiFfiConverterSequenceString.read(buf),
            )
        if variant == 2:
            return Witness.HTLC(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterOptionalSequenceString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_P2PK():
            _UniffiFfiConverterSequenceString.check_lower(value.signatures)
            return
        if value.is_HTLC():
            _UniffiFfiConverterString.check_lower(value.preimage)
            _UniffiFfiConverterOptionalSequenceString.check_lower(value.signatures)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_P2PK():
            buf.write_i32(1)
            _UniffiFfiConverterSequenceString.write(value.signatures, buf)
        if value.is_HTLC():
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.preimage, buf)
            _UniffiFfiConverterOptionalSequenceString.write(value.signatures, buf)



class _UniffiFfiConverterOptionalTypeWitness(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeWitness.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeWitness.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeWitness.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")

