class _UniffiFfiConverterSequenceTypePaymentRequest(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypePaymentRequest.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypePaymentRequest.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypePaymentRequest.read(buf) for i in range(count)
        ]

@dataclass
class ParsedPaymentInstruction:
    """
    A parsed BIP 321 payment instruction containing all payment methods found.

    After parsing, inspect the lists to determine which payment methods are
    available and choose the best one for your wallet. A single URI can contain
    multiple methods (e.g. cashu + BOLT11 + on-chain) to give the payer options.

    # Examples

    ```text
    // Parse a BIP 321 URI that bundles cashu, BOLT11, and an on-chain address
    val parsed = parseBip321PaymentInstruction(
    "bitcoin:bc1qar0s...?creq=CREQB1...&lightning=lnbc100n1p..."
    )

    // Check which payment methods are available and pick one
    when {
    parsed.cashuRequests.isNotEmpty() -> {
    // Prefer ecash: instant settlement, zero fees
    val request = parsed.cashuRequests.first()
    val id = request.paymentId()         // e.g. "b7a90176"
    val amount = request.amount()         // e.g. Amount(10)
    val unit = request.unit()             // e.g. CurrencyUnit.Sat
    val mints = request.mints()           // acceptable mint URLs
    val transports = request.transports() // how to deliver proofs
    }
    parsed.bolt11Invoices.isNotEmpty() -> {
    // Fall back to Lightning BOLT11
    val invoice = parsed.bolt11Invoices.first()
    }
    parsed.bolt12Offers.isNotEmpty() -> {
    // Fall back to Lightning BOLT12
    val offer = parsed.bolt12Offers.first()
    }
    parsed.onchainAddresses.isNotEmpty() -> {
    // Last resort: on-chain payment
    val address = parsed.onchainAddresses.first()
    }
    }

    // Amount info
    val msats = parsed.amountMsats           // fixed amount in msats, or null
    val flexible = parsed.isConfigurableAmount // true if payer chooses amount
    val desc = parsed.description             // URI label/message, or null
    ```
"""
    def __init__(self, *, cashu_requests:typing.List[PaymentRequest], bolt11_invoices:typing.List[str], bolt12_offers:typing.List[str], onchain_addresses:typing.List[str], description:typing.Optional[str], amount_msats:typing.Optional[int], is_configurable_amount:bool):
        self.cashu_requests = cashu_requests
        self.bolt11_invoices = bolt11_invoices
        self.bolt12_offers = bolt12_offers
        self.onchain_addresses = onchain_addresses
        self.description = description
        self.amount_msats = amount_msats
        self.is_configurable_amount = is_configurable_amount
        
        

    
    def __str__(self):
        return "ParsedPaymentInstruction(cashu_requests={}, bolt11_invoices={}, bolt12_offers={}, onchain_addresses={}, description={}, amount_msats={}, is_configurable_amount={})".format(self.cashu_requests, self.bolt11_invoices, self.bolt12_offers, self.onchain_addresses, self.description, self.amount_msats, self.is_configurable_amount)
    def __eq__(self, other):
        if self.cashu_requests != other.cashu_requests:
            return False
        if self.bolt11_invoices != other.bolt11_invoices:
            return False
        if self.bolt12_offers != other.bolt12_offers:
            return False
        if self.onchain_addresses != other.onchain_addresses:
            return False
        if self.description != other.description:
            return False
        if self.amount_msats != other.amount_msats:
            return False
        if self.is_configurable_amount != other.is_configurable_amount:
            return False
        return True

