class ProofState(enum.Enum):
    """
    FFI-compatible Proof state
"""
    
    UNSPENT = 0
    
    PENDING = 1
    
    SPENT = 2
    
    RESERVED = 3
    
    PENDING_SPENT = 4
    


class _UniffiFfiConverterTypeProofState(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ProofState.UNSPENT
        if variant == 2:
            return ProofState.PENDING
        if variant == 3:
            return ProofState.SPENT
        if variant == 4:
            return ProofState.RESERVED
        if variant == 5:
            return ProofState.PENDING_SPENT
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == ProofState.UNSPENT:
            return
        if value == ProofState.PENDING:
            return
        if value == ProofState.SPENT:
            return
        if value == ProofState.RESERVED:
            return
        if value == ProofState.PENDING_SPENT:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == ProofState.UNSPENT:
            buf.write_i32(1)
        if value == ProofState.PENDING:
            buf.write_i32(2)
        if value == ProofState.SPENT:
            buf.write_i32(3)
        if value == ProofState.RESERVED:
            buf.write_i32(4)
        if value == ProofState.PENDING_SPENT:
            buf.write_i32(5)



class _UniffiFfiConverterOptionalTypeConditions(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeConditions.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeConditions.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeConditions.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")






class SpendingConditions:
    """
    FFI-compatible SpendingConditions
"""
    def __init__(self):
        raise RuntimeError("SpendingConditions cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class P2PK:
        """
        P2PK (Pay to Public Key) conditions
"""
        
        def __init__(self, pubkey:str, conditions:typing.Optional[Conditions]):
            self.pubkey = pubkey
            
            """
        The public key (as hex string)
"""
        
            self.conditions = conditions
            
            """
        Additional conditions
"""
        
            pass

    
            
            
    
        def __str__(self):
            return "SpendingConditions.P2PK(pubkey={}, conditions={})".format(self.pubkey, self.conditions)
        def __eq__(self, other):
            if not other.is_P2PK():
                return False
            if self.pubkey != other.pubkey:
                return False
            if self.conditions != other.conditions:
                return False
            return True

    @dataclass
    class HTLC:
        """
        HTLC (Hash Time Locked Contract) conditions
"""
        
        def __init__(self, hash:str, conditions:typing.Optional[Conditions]):
            self.hash = hash
            
            """
        Hash of the preimage (as hex string)
"""
        
            self.conditions = conditions
            
            """
        Additional conditions
"""
        
            pass

    
            
            
    
        def __str__(self):
            return "SpendingConditions.HTLC(hash={}, conditions={})".format(self.hash, self.conditions)
        def __eq__(self, other):
            if not other.is_HTLC():
                return False
            if self.hash != other.hash:
                return False
            if self.conditions != other.conditions:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_P2PK(self) -> bool:
        return isinstance(self, SpendingConditions.P2PK)
    def is_p2pk(self) -> bool:
        return isinstance(self, SpendingConditions.P2PK)
    def is_HTLC(self) -> bool:
        return isinstance(self, SpendingConditions.HTLC)
    def is_htlc(self) -> bool:
        return isinstance(self, SpendingConditions.HTLC)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
SpendingConditions.P2PK = type("SpendingConditions.P2PK", (SpendingConditions.P2PK, SpendingConditions,), {})  # type: ignore
SpendingConditions.HTLC = type("SpendingConditions.HTLC", (SpendingConditions.HTLC, SpendingConditions,), {})  # type: ignore




class _UniffiFfiConverterTypeSpendingConditions(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return SpendingConditions.P2PK(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterOptionalTypeConditions.read(buf),
            )
        if variant == 2:
            return SpendingConditions.HTLC(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterOptionalTypeConditions.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_P2PK():
            _UniffiFfiConverterString.check_lower(value.pubkey)
            _UniffiFfiConverterOptionalTypeConditions.check_lower(value.conditions)
            return
        if value.is_HTLC():
            _UniffiFfiConverterString.check_lower(value.hash)
            _UniffiFfiConverterOptionalTypeConditions.check_lower(value.conditions)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_P2PK():
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.pubkey, buf)
            _UniffiFfiConverterOptionalTypeConditions.write(value.conditions, buf)
        if value.is_HTLC():
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.hash, buf)
            _UniffiFfiConverterOptionalTypeConditions.write(value.conditions, buf)



class _UniffiFfiConverterOptionalTypeSpendingConditions(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeSpendingConditions.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeSpendingConditions.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeSpendingConditions.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")

