class _UniffiFfiConverterOptionalTypeSendMemo(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeSendMemo.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeSendMemo.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeSendMemo.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")






class SendKind:
    """
    FFI-compatible SendKind
"""
    def __init__(self):
        raise RuntimeError("SendKind cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class ONLINE_EXACT:
        """
        Allow online swap before send if wallet does not have exact amount
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "SendKind.ONLINE_EXACT()".format()
        def __eq__(self, other):
            if not other.is_ONLINE_EXACT():
                return False
            return True

    @dataclass
    class ONLINE_TOLERANCE:
        """
        Prefer offline send if difference is less than tolerance
"""
        
        def __init__(self, tolerance:Amount):
            self.tolerance = tolerance
            
            
            pass

    
            
            
    
        def __str__(self):
            return "SendKind.ONLINE_TOLERANCE(tolerance={})".format(self.tolerance)
        def __eq__(self, other):
            if not other.is_ONLINE_TOLERANCE():
                return False
            if self.tolerance != other.tolerance:
                return False
            return True

    @dataclass
    class OFFLINE_EXACT:
        """
        Wallet cannot do an online swap and selected proof must be exactly send amount
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "SendKind.OFFLINE_EXACT()".format()
        def __eq__(self, other):
            if not other.is_OFFLINE_EXACT():
                return False
            return True

    @dataclass
    class OFFLINE_TOLERANCE:
        """
        Wallet must remain offline but can over pay if below tolerance
"""
        
        def __init__(self, tolerance:Amount):
            self.tolerance = tolerance
            
            
            pass

    
            
            
    
        def __str__(self):
            return "SendKind.OFFLINE_TOLERANCE(tolerance={})".format(self.tolerance)
        def __eq__(self, other):
            if not other.is_OFFLINE_TOLERANCE():
                return False
            if self.tolerance != other.tolerance:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_ONLINE_EXACT(self) -> bool:
        return isinstance(self, SendKind.ONLINE_EXACT)
    def is_online_exact(self) -> bool:
        return isinstance(self, SendKind.ONLINE_EXACT)
    def is_ONLINE_TOLERANCE(self) -> bool:
        return isinstance(self, SendKind.ONLINE_TOLERANCE)
    def is_online_tolerance(self) -> bool:
        return isinstance(self, SendKind.ONLINE_TOLERANCE)
    def is_OFFLINE_EXACT(self) -> bool:
        return isinstance(self, SendKind.OFFLINE_EXACT)
    def is_offline_exact(self) -> bool:
        return isinstance(self, SendKind.OFFLINE_EXACT)
    def is_OFFLINE_TOLERANCE(self) -> bool:
        return isinstance(self, SendKind.OFFLINE_TOLERANCE)
    def is_offline_tolerance(self) -> bool:
        return isinstance(self, SendKind.OFFLINE_TOLERANCE)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
SendKind.ONLINE_EXACT = type("SendKind.ONLINE_EXACT", (SendKind.ONLINE_EXACT, SendKind,), {})  # type: ignore
SendKind.ONLINE_TOLERANCE = type("SendKind.ONLINE_TOLERANCE", (SendKind.ONLINE_TOLERANCE, SendKind,), {})  # type: ignore
SendKind.OFFLINE_EXACT = type("SendKind.OFFLINE_EXACT", (SendKind.OFFLINE_EXACT, SendKind,), {})  # type: ignore
SendKind.OFFLINE_TOLERANCE = type("SendKind.OFFLINE_TOLERANCE", (SendKind.OFFLINE_TOLERANCE, SendKind,), {})  # type: ignore




class _UniffiFfiConverterTypeSendKind(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return SendKind.ONLINE_EXACT(
            )
        if variant == 2:
            return SendKind.ONLINE_TOLERANCE(
                _UniffiFfiConverterTypeAmount.read(buf),
            )
        if variant == 3:
            return SendKind.OFFLINE_EXACT(
            )
        if variant == 4:
            return SendKind.OFFLINE_TOLERANCE(
                _UniffiFfiConverterTypeAmount.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_ONLINE_EXACT():
            return
        if value.is_ONLINE_TOLERANCE():
            _UniffiFfiConverterTypeAmount.check_lower(value.tolerance)
            return
        if value.is_OFFLINE_EXACT():
            return
        if value.is_OFFLINE_TOLERANCE():
            _UniffiFfiConverterTypeAmount.check_lower(value.tolerance)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_ONLINE_EXACT():
            buf.write_i32(1)
        if value.is_ONLINE_TOLERANCE():
            buf.write_i32(2)
            _UniffiFfiConverterTypeAmount.write(value.tolerance, buf)
        if value.is_OFFLINE_EXACT():
            buf.write_i32(3)
        if value.is_OFFLINE_TOLERANCE():
            buf.write_i32(4)
            _UniffiFfiConverterTypeAmount.write(value.tolerance, buf)








