class RateLimit:
    """
    Client-side request pacing for a wallet's mint traffic.

    A wallet starts with whatever [`WalletConfig::rate_limit`] selected, which
    defaults to the built-in pacing so it stays under a mint's per-minute request
    cap. Pass one of these to [`Wallet::set_rate_limit`] to change it on a live
    wallet.

    # Example

    ```ignore
    // Turn pacing off (e.g. a mint with no request cap).
    wallet.set_rate_limit(RateLimit::Disabled)?;

    // Restore the built-in default pacing.
    wallet.set_rate_limit(RateLimit::Default)?;

    // Allow a burst of 20 requests, refilling 60 per minute.
    wallet.set_rate_limit(RateLimit::Custom {
    capacity: 20,
    refill_per_minute: 60,
    })?;
    ```
"""
    def __init__(self):
        raise RuntimeError("RateLimit cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class DEFAULT:
        """
        Built-in default pacing (capacity 20, refill 20/min).
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "RateLimit.DEFAULT()".format()
        def __eq__(self, other):
            if not other.is_DEFAULT():
                return False
            return True

    @dataclass
    class DISABLED:
        """
        No client-side pacing.
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "RateLimit.DISABLED()".format()
        def __eq__(self, other):
            if not other.is_DISABLED():
                return False
            return True

    @dataclass
    class CUSTOM:
        """
        Custom burst capacity and per-minute refill. Both must be non-zero.
"""
        
        def __init__(self, capacity:int, refill_per_minute:int):
            self.capacity = capacity
            
            """
        Maximum burst: requests allowed back-to-back before pacing kicks in.
"""
        
            self.refill_per_minute = refill_per_minute
            
            """
        Sustained rate: requests earned back per minute.
"""
        
            pass

    
            
            
    
        def __str__(self):
            return "RateLimit.CUSTOM(capacity={}, refill_per_minute={})".format(self.capacity, self.refill_per_minute)
        def __eq__(self, other):
            if not other.is_CUSTOM():
                return False
            if self.capacity != other.capacity:
                return False
            if self.refill_per_minute != other.refill_per_minute:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_DEFAULT(self) -> bool:
        return isinstance(self, RateLimit.DEFAULT)
    def is_default(self) -> bool:
        return isinstance(self, RateLimit.DEFAULT)
    def is_DISABLED(self) -> bool:
        return isinstance(self, RateLimit.DISABLED)
    def is_disabled(self) -> bool:
        return isinstance(self, RateLimit.DISABLED)
    def is_CUSTOM(self) -> bool:
        return isinstance(self, RateLimit.CUSTOM)
    def is_custom(self) -> bool:
        return isinstance(self, RateLimit.CUSTOM)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
RateLimit.DEFAULT = type("RateLimit.DEFAULT", (RateLimit.DEFAULT, RateLimit,), {})  # type: ignore
RateLimit.DISABLED = type("RateLimit.DISABLED", (RateLimit.DISABLED, RateLimit,), {})  # type: ignore
RateLimit.CUSTOM = type("RateLimit.CUSTOM", (RateLimit.CUSTOM, RateLimit,), {})  # type: ignore




class _UniffiFfiConverterTypeRateLimit(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return RateLimit.DEFAULT(
            )
        if variant == 2:
            return RateLimit.DISABLED(
            )
        if variant == 3:
            return RateLimit.CUSTOM(
                _UniffiFfiConverterUInt32.read(buf),
                _UniffiFfiConverterUInt32.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_DEFAULT():
            return
        if value.is_DISABLED():
            return
        if value.is_CUSTOM():
            _UniffiFfiConverterUInt32.check_lower(value.capacity)
            _UniffiFfiConverterUInt32.check_lower(value.refill_per_minute)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_DEFAULT():
            buf.write_i32(1)
        if value.is_DISABLED():
            buf.write_i32(2)
        if value.is_CUSTOM():
            buf.write_i32(3)
            _UniffiFfiConverterUInt32.write(value.capacity, buf)
            _UniffiFfiConverterUInt32.write(value.refill_per_minute, buf)



class _UniffiFfiConverterOptionalTypeRateLimit(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeRateLimit.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeRateLimit.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeRateLimit.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")

