class WalletDatabase():
    """
    FFI-compatible wallet database trait with all read and write operations
    This trait mirrors the CDK WalletDatabase trait structure
"""
    
    async def get_mint(self, mint_url: MintUrl) -> typing.Optional[MintInfo]:
        """
        Get mint from storage
"""
        raise NotImplementedError
    async def get_mints(self, ) -> dict[MintUrl, typing.Optional[MintInfo]]:
        """
        Get all mints from storage
"""
        raise NotImplementedError
    async def get_mint_keysets(self, mint_url: MintUrl) -> typing.Optional[typing.List[KeySetInfo]]:
        """
        Get mint keysets for mint url
"""
        raise NotImplementedError
    async def get_keyset_by_id(self, keyset_id: Id) -> typing.Optional[KeySetInfo]:
        """
        Get mint keyset by id
"""
        raise NotImplementedError
    async def get_mint_quote(self, quote_id: str) -> typing.Optional[MintQuote]:
        """
        Get mint quote from storage
"""
        raise NotImplementedError
    async def get_mint_quotes(self, ) -> typing.List[MintQuote]:
        """
        Get mint quotes from storage
"""
        raise NotImplementedError
    async def get_unissued_mint_quotes(self, ) -> typing.List[MintQuote]:
        """
        Get unissued mint quotes from storage
        Returns bolt11 quotes where nothing has been issued yet (amount_issued = 0) and all bolt12 quotes.
"""
        raise NotImplementedError
    async def get_melt_quote(self, quote_id: str) -> typing.Optional[MeltQuote]:
        """
        Get melt quote from storage
"""
        raise NotImplementedError
    async def get_melt_quotes(self, ) -> typing.List[MeltQuote]:
        """
        Get melt quotes from storage
"""
        raise NotImplementedError
    async def get_keys(self, id: Id) -> typing.Optional[Keys]:
        """
        Get Keys from storage
"""
        raise NotImplementedError
    async def get_proofs(self, mint_url: typing.Optional[MintUrl],unit: typing.Optional[CurrencyUnit],state: typing.Optional[typing.List[ProofState]],spending_conditions: typing.Optional[typing.List[SpendingConditions]]) -> typing.List[ProofInfo]:
        """
        Get proofs from storage
"""
        raise NotImplementedError
    async def get_proofs_by_ys(self, ys: typing.List[PublicKey]) -> typing.List[ProofInfo]:
        """
        Get proofs by Y values
"""
        raise NotImplementedError
    async def get_balance(self, mint_url: typing.Optional[MintUrl],unit: typing.Optional[CurrencyUnit],state: typing.Optional[typing.List[ProofState]]) -> int:
        """
        Get balance efficiently using SQL aggregation
"""
        raise NotImplementedError
    async def get_transaction(self, transaction_id: TransactionId) -> typing.Optional[Transaction]:
        """
        Get transaction from storage
"""
        raise NotImplementedError
    async def list_transactions(self, mint_url: typing.Optional[MintUrl],direction: typing.Optional[TransactionDirection],unit: typing.Optional[CurrencyUnit]) -> typing.List[Transaction]:
        """
        List transactions from storage
"""
        raise NotImplementedError
    async def kv_read(self, primary_namespace: str,secondary_namespace: str,key: str) -> typing.Optional[bytes]:
        """
        Read a value from the KV store
"""
        raise NotImplementedError
    async def kv_list(self, primary_namespace: str,secondary_namespace: str) -> typing.List[str]:
        """
        List keys in a namespace
"""
        raise NotImplementedError
    async def add_p2pk_key(self, pubkey: PublicKey,derivation_path: str,derivation_index: int) -> None:
        """
        Add P2PK signing key to storage
"""
        raise NotImplementedError
    async def get_p2pk_key(self, pubkey: PublicKey) -> typing.Optional[P2pkSigningKey]:
        """
        Get P2PK signing key from storage
"""
        raise NotImplementedError
    async def list_p2pk_keys(self, ) -> typing.List[P2pkSigningKey]:
        """
        List all P2PK signing keys from storage
"""
        raise NotImplementedError
    async def latest_p2pk(self, ) -> typing.Optional[P2pkSigningKey]:
        """
        Get the latest P2PK signing key (most recently created)
"""
        raise NotImplementedError
    async def kv_write(self, primary_namespace: str,secondary_namespace: str,key: str,value: bytes) -> None:
        """
        Write a value to the KV store
"""
        raise NotImplementedError
    async def kv_remove(self, primary_namespace: str,secondary_namespace: str,key: str) -> None:
        """
        Remove a value from the KV store
"""
        raise NotImplementedError
    async def update_proofs(self, added: typing.List[ProofInfo],removed_ys: typing.List[PublicKey]) -> None:
        """
        Update the proofs in storage by adding new proofs or removing proofs by their Y value
"""
        raise NotImplementedError
    async def update_proofs_state(self, ys: typing.List[PublicKey],state: ProofState) -> None:
        """
        Update proofs state in storage
"""
        raise NotImplementedError
    async def add_transaction(self, transaction: Transaction) -> None:
        """
        Add transaction to storage
"""
        raise NotImplementedError
    async def remove_transaction(self, transaction_id: TransactionId) -> None:
        """
        Remove transaction from storage
"""
        raise NotImplementedError
    async def update_mint_url(self, old_mint_url: MintUrl,new_mint_url: MintUrl) -> None:
        """
        Update mint url
"""
        raise NotImplementedError
    async def increment_keyset_counter(self, keyset_id: Id,count: int) -> int:
        """
        Atomically increment Keyset counter and return new value
"""
        raise NotImplementedError
    async def increment_derivation_counter(self, namespace: str,count: int) -> int:
        """
        Atomically increment a namespaced derivation counter and return its new value.
"""
        raise NotImplementedError
    async def add_mint(self, mint_url: MintUrl,mint_info: typing.Optional[MintInfo]) -> None:
        """
        Add Mint to storage
"""
        raise NotImplementedError
    async def remove_mint(self, mint_url: MintUrl) -> None:
        """
        Remove Mint from storage
"""
        raise NotImplementedError
    async def add_mint_keysets(self, mint_url: MintUrl,keysets: typing.List[KeySetInfo]) -> None:
        """
        Add mint keyset to storage
"""
        raise NotImplementedError
    async def add_mint_quote(self, quote: MintQuote) -> None:
        """
        Add mint quote to storage
"""
        raise NotImplementedError
    async def remove_mint_quote(self, quote_id: str) -> None:
        """
        Remove mint quote from storage
"""
        raise NotImplementedError
    async def add_melt_quote(self, quote: MeltQuote) -> None:
        """
        Add melt quote to storage
"""
        raise NotImplementedError
    async def remove_melt_quote(self, quote_id: str) -> None:
        """
        Remove melt quote from storage
"""
        raise NotImplementedError
    async def add_keys(self, keyset: KeySet) -> None:
        """
        Add Keys to storage
"""
        raise NotImplementedError
    async def remove_keys(self, id: Id) -> None:
        """
        Remove Keys from storage
"""
        raise NotImplementedError
    async def add_saga(self, saga_json: str) -> None:
        """
        Add a wallet saga to storage (JSON serialized)
"""
        raise NotImplementedError
    async def get_saga(self, id: str) -> typing.Optional[str]:
        """
        Get a wallet saga by ID (returns JSON serialized)
"""
        raise NotImplementedError
    async def update_saga(self, saga_json: str) -> bool:
        """
        Update a wallet saga (JSON serialized) with optimistic locking.

        Returns `true` if the update succeeded (version matched),
        `false` if another instance modified the saga first.
"""
        raise NotImplementedError
    async def delete_saga(self, id: str) -> None:
        """
        Delete a wallet saga
"""
        raise NotImplementedError
    async def get_incomplete_sagas(self, ) -> typing.List[str]:
        """
        Get all incomplete sagas (returns JSON serialized sagas)
"""
        raise NotImplementedError
    async def reserve_proofs(self, ys: typing.List[PublicKey],operation_id: str) -> None:
        """
        Reserve proofs for an operation
"""
        raise NotImplementedError
    async def release_proofs(self, operation_id: str) -> None:
        """
        Release live proofs reserved by an operation.

        Implementations must only change Reserved or Pending proofs owned by
        `operation_id`; Spent proofs and proofs owned by another operation must
        be preserved.
"""
        raise NotImplementedError
    async def get_reserved_proofs(self, operation_id: str) -> typing.List[ProofInfo]:
        """
        Get proofs reserved by an operation
"""
        raise NotImplementedError
    async def reserve_melt_quote(self, quote_id: str,operation_id: str) -> None:
        """
        Reserve a melt quote for an operation
"""
        raise NotImplementedError
    async def release_melt_quote(self, operation_id: str) -> None:
        """
        Release a melt quote reserved by an operation
"""
        raise NotImplementedError
    async def reserve_mint_quote(self, quote_id: str,operation_id: str) -> None:
        """
        Reserve a mint quote for an operation
"""
        raise NotImplementedError
    async def release_mint_quote(self, operation_id: str) -> None:
        """
        Release a mint quote reserved by an operation
"""
        raise NotImplementedError

class WalletDatabaseImpl(WalletDatabase):
    """
    FFI-compatible wallet database trait with all read and write operations
    This trait mirrors the CDK WalletDatabase trait structure
"""
    
    _handle: ctypes.c_uint64
    
    def __init__(self, *args, **kwargs):
        raise ValueError("This class has no default constructor")

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_cdk_ffi_fn_free_walletdatabase, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_cdk_ffi_fn_clone_walletdatabase, self._handle)

