class _UniffiFfiConverterTypeWalletDatabase:
    _handle_map = _UniffiHandleMap()

    @staticmethod
    def lift(value: int):
        if (value & 1) == 0:
            # Rust-generated handle, construct a new class that uses the handle to implement the
            # interface
            return WalletDatabaseImpl._uniffi_make_instance(value)
        else:
            # Python-generated handle, get the object from the handle map
            return _UniffiFfiConverterTypeWalletDatabase._handle_map.remove(value)

    @staticmethod
    def check_lower(value: WalletDatabase):
        if not isinstance(value, WalletDatabase):
            raise TypeError("Expected WalletDatabase subclass, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: WalletDatabase):
         if isinstance(value, WalletDatabaseImpl):
            # Rust-implementated object.  Clone the handle and return it
            return value._uniffi_clone_handle()
         else:
            # Python-implementated object, generate a new vtable handle and return that.
            return _UniffiFfiConverterTypeWalletDatabase._handle_map.insert(value)

    @classmethod
    def read(cls, buf: _UniffiRustBuffer):
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: WalletDatabase, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))






class WalletStore:
    """
    Unified wallet storage: either a built-in Rust backend or a custom
    foreign-language implementation of the `WalletDatabase` callback interface.

    Wallet methods can write to this store from FFI calls that mint, receive,
    recover, subscribe, or check quote/proof state. Mobile host apps own platform
    lifecycle handling for the chosen backend: use a durable app-owned location,
    pause or cancel wallet work when backgrounding unless background storage
    activity is intended, and use platform facilities such as iOS
    `beginBackgroundTask` when writes must finish after a lifecycle transition.

    This is an enum rather than accepting `WalletDatabase` directly because UniFFI
    does not support trait objects as constructor parameters — only callback interfaces
    wrapped in `Arc<dyn Trait>` inside an enum variant work across the FFI boundary.
"""
    def __init__(self):
        raise RuntimeError("WalletStore cannot be instantiated directly")

