class Wallet(WalletProtocol):
    """
    FFI-compatible wallet.

    Wallet methods can write to the configured local store while they perform
    mint, receive, recovery, subscription, and status operations. Mobile host
    apps own platform lifecycle handling around these calls: pause or cancel work
    when moving to the background unless background network and storage activity
    is intended, and use platform facilities such as iOS `beginBackgroundTask`
    when an operation must finish after a lifecycle transition.
"""
    
    _handle: ctypes.c_uint64
    def __init__(self, mint_url: str,unit: CurrencyUnit,mnemonic: str,store: WalletStore,config: WalletConfig):
        """
        Create a new wallet.

        The returned wallet uses `store` for local state. FFI wallet methods may
        write to that store later, so mobile host apps are responsible for
        choosing durable storage locations and coordinating lifecycle transitions
        around wallet calls. For example, use iOS `beginBackgroundTask` if a
        write-capable operation must continue after the app backgrounds.

        Accepts a `WalletStore` which can be:
        - `Sqlite { path }` — built-in Rust SQLite backend
        - `Postgres { url }` — built-in Rust Postgres backend
        - `Custom { db }` — foreign-language implementation of `WalletDatabase`
"""
        
        _UniffiFfiConverterString.check_lower(mint_url)
        
        _UniffiFfiConverterTypeCurrencyUnit.check_lower(unit)
        
        _UniffiFfiConverterString.check_lower(mnemonic)
        
        _UniffiFfiConverterTypeWalletStore.check_lower(store)
        
        _UniffiFfiConverterTypeWalletConfig.check_lower(config)
        _uniffi_lowered_args = (
            _UniffiFfiConverterString.lower(mint_url),
            _UniffiFfiConverterTypeCurrencyUnit.lower(unit),
            _UniffiFfiConverterString.lower(mnemonic),
            _UniffiFfiConverterTypeWalletStore.lower(store),
            _UniffiFfiConverterTypeWalletConfig.lower(config),
        )
        _uniffi_lift_return = _UniffiFfiConverterTypeWallet.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeFfiError
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_cdk_ffi_fn_constructor_wallet_new,
            *_uniffi_lowered_args,
        )
        self._handle = _uniffi_ffi_result

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_cdk_ffi_fn_free_wallet, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_cdk_ffi_fn_clone_wallet, self._handle)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _uniffi_make_instance(cls, handle):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required handle.
        inst = cls.__new__(cls)
        inst._handle = handle
        return inst
    async def active_keyset(self, ) -> KeySet:
        """
        Get the active keyset with the lowest fees
"""
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
        )
        _uniffi_lift_return = _UniffiFfiConverterTypeKeySet.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeFfiError
        return await _uniffi_rust_call_async(
            _UniffiLib.uniffi_cdk_ffi_fn_method_wallet_active_keyset(*_uniffi_lowered_args),
            _UniffiLib.ffi_cdk_ffi_rust_future_poll_rust_buffer,
            _UniffiLib.ffi_cdk_ffi_rust_future_complete_rust_buffer,
            _UniffiLib.ffi_cdk_ffi_rust_future_free_rust_buffer,
            _uniffi_lift_return,
            _uniffi_error_converter,
        )
    async def calculate_fee(self, proof_count: int,keyset_id: str) -> Amount:
        """
        Calculate fee for a given number of proofs with the specified keyset
"""
        
        _UniffiFfiConverterUInt32.check_lower(proof_count)
        
        _UniffiFfiConverterString.check_lower(keyset_id)
