class _UniffiFfiConverterTypeWallet:
    @staticmethod
    def lift(value: int) -> Wallet:
        return Wallet._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Wallet):
        if not isinstance(value, Wallet):
            raise TypeError("Expected Wallet instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Wallet) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Wallet:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Wallet, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

class _UniffiFfiConverterMapTypeWalletKeyTypeAmount(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, items):
        for (key, value) in items.items():
            _UniffiFfiConverterTypeWalletKey.check_lower(key)
            _UniffiFfiConverterTypeAmount.check_lower(value)

    @classmethod
    def write(cls, items, buf):
        buf.write_i32(len(items))
        for (key, value) in items.items():
            _UniffiFfiConverterTypeWalletKey.write(key, buf)
            _UniffiFfiConverterTypeAmount.write(value, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative map size")

        # It would be nice to use a dict comprehension,
        # but in Python 3.7 and before the evaluation order is not according to spec,
        # so we we're reading the value before the key.
        # This loop makes the order explicit: first reading the key, then the value.
        d = {}
        for i in range(count):
            key = _UniffiFfiConverterTypeWalletKey.read(buf)
            val = _UniffiFfiConverterTypeAmount.read(buf)
            d[key] = val
        return d

class _UniffiFfiConverterSequenceTypeWallet(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeWallet.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeWallet.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeWallet.read(buf) for i in range(count)
        ]


class WalletRepositoryProtocol(typing.Protocol):
    """
    FFI-compatible WalletRepository
"""
    
    async def backup_mints(self, relays: typing.List[str],options: BackupOptions) -> BackupResult:
        """
        Backup the current mint list to Nostr relays using NUT-27.
"""
        raise NotImplementedError
    async def create_wallet(self, mint_url: MintUrl,unit: typing.Optional[CurrencyUnit],target_proof_count: typing.Optional[int]) -> None:
        """
        Add a mint to this WalletRepository
"""
        raise NotImplementedError
    async def fetch_mint_backup(self, relays: typing.List[str],options: RestoreOptions) -> MintBackup:
        """
        Fetch the NUT-27 mint backup without adding mints to the repository.
"""
        raise NotImplementedError
    async def flush_rate_limits(self, ) -> None:
        """
        Wait until the rate-limit budgets drawn down by every wallet in this
        repository have been handed to storage.

        Await this before dropping the repository on shutdown. Without it,
        persistence is best effort and a rebuild can outrun the detached
        writer, so every rebuilt wallet starts with a full burst against the
        mint's rate cap.
"""
        raise NotImplementedError
    async def get_balances(self, ) -> dict[WalletKey, Amount]:
        """
        Get wallet balances for all mints
"""
        raise NotImplementedError
    async def get_or_create_wallet(self, mint_url: MintUrl,unit: CurrencyUnit,target_proof_count: typing.Optional[int]) -> Wallet:
        """
        Get the wallet for a mint URL and unit, creating it if it does not exist

        Unlike `create_wallet`, an existing wallet is returned untouched: its
        configuration is not replaced.
"""
        raise NotImplementedError
    async def get_token_data(self, token: Token) -> TokenData:
        """
        Get token data, including the expected redemption fee, without redeeming it.
"""
        raise NotImplementedError
    async def get_wallet(self, mint_url: MintUrl,unit: CurrencyUnit) -> Wallet:
        """
        Get a specific wallet from WalletRepository by mint URL

        Returns an error if no wallet exists for the given mint URL.
"""
        raise NotImplementedError
    async def get_wallets(self, ) -> typing.List[Wallet]:
        """
        Get all wallets from WalletRepository
"""
        raise NotImplementedError
    async def has_mint(self, mint_url: MintUrl) -> bool:
        """
        Check if mint is in wallet
"""
        raise NotImplementedError
    def is_rate_limited(self, ) -> bool:
        """
        Whether this repository is pacing requests right now.

        Wallets reached through a proxy or Tor are built with a custom client,
        so they report false even while this is true.
"""
        raise NotImplementedError
    def mint_backup_public_key(self, ) -> str:
        """
        Get the NUT-27 mint backup public key as hex.
"""
        raise NotImplementedError
    async def remove_wallet(self, mint_url: MintUrl,currency_unit: CurrencyUnit) -> None:
        """
        Remove mint from WalletRepository
"""
        raise NotImplementedError
    async def restore_mints(self, relays: typing.List[str],add_mints: bool,options: RestoreOptions) -> RestoreResult:
        """
        Restore the mint list from Nostr relays using NUT-27.
"""
        raise NotImplementedError
    async def set_metadata_cache_ttl_for_all_mints(self, ttl_secs: typing.Optional[int]) -> None:
        """
        Set metadata cache TTL (time-to-live) in seconds for all mints

        Controls how long cached mint metadata is considered fresh for all mints
        in this WalletRepository.

        # Arguments

        * `ttl_secs` - Optional TTL in seconds. If None, cache never expires for any mint.
"""
        raise NotImplementedError
    async def set_metadata_cache_ttl_for_mint(self, mint_url: MintUrl,ttl_secs: typing.Optional[int]) -> None:
        """
        Set metadata cache TTL (time-to-live) in seconds for a specific mint

        Controls how long cached mint metadata (keysets, keys, mint info) is considered fresh
        before requiring a refresh from the mint server for a specific mint.

        # Arguments

        * `mint_url` - The mint URL to set the TTL for
        * `ttl_secs` - Optional TTL in seconds. If None, cache never expires.
"""
        raise NotImplementedError
    def set_rate_limit(self, rate_limit: RateLimit) -> None:
        """
        Change client-side request rate limiting for every wallet here.

        Pacing is repository-wide because one limiter is shared, which is why
        `create_wallet` and `get_or_create_wallet` take no rate limit: a
        per-wallet value would silently reconfigure its siblings. Repository
        construction makes no network requests, so calling this immediately
        after `new` is equivalent to configuring it through `new_with_config`.

        Returns an error if a `Custom` value has a zero field.
"""
        raise NotImplementedError

class WalletRepository(WalletRepositoryProtocol):
    """
    FFI-compatible WalletRepository
"""
    
    _handle: ctypes.c_uint64
    def __init__(self, mnemonic: str,store: WalletStore):
        """
        Create a new WalletRepository from locally persisted wallet state.

        Construction does not make network requests to configured mints.

        Accepts a `WalletStore` which can be:
        - `Sqlite { path }` — built-in Rust SQLite backend
        - `Postgres { url }` — built-in Rust Postgres backend
        - `Custom { db }` — foreign-language implementation of `WalletDatabase`
"""
        
        _UniffiFfiConverterString.check_lower(mnemonic)
        
        _UniffiFfiConverterTypeWalletStore.check_lower(store)
        _uniffi_lowered_args = (
            _UniffiFfiConverterString.lower(mnemonic),
            _UniffiFfiConverterTypeWalletStore.lower(store),
        )
        _uniffi_lift_return = _UniffiFfiConverterTypeWalletRepository.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeFfiError
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_cdk_ffi_fn_constructor_walletrepository_new,
            *_uniffi_lowered_args,
        )
        self._handle = _uniffi_ffi_result
    @classmethod
    def new_with_config(cls, mnemonic: str,store: WalletStore,config: WalletRepositoryConfig) -> WalletRepository:
        """
        Create a new WalletRepository with proxy and rate-limit configuration.

        Construction restores locally persisted wallet state without making
        network requests to configured mints.
"""
        
        _UniffiFfiConverterString.check_lower(mnemonic)
        
        _UniffiFfiConverterTypeWalletStore.check_lower(store)
        
        _UniffiFfiConverterTypeWalletRepositoryConfig.check_lower(config)
        _uniffi_lowered_args = (
            _UniffiFfiConverterString.lower(mnemonic),
            _UniffiFfiConverterTypeWalletStore.lower(store),
            _UniffiFfiConverterTypeWalletRepositoryConfig.lower(config),
        )
        _uniffi_lift_return = _UniffiFfiConverterTypeWalletRepository.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeFfiError
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_cdk_ffi_fn_constructor_walletrepository_new_with_config,
            *_uniffi_lowered_args,
        )
        return cls._uniffi_make_instance(_uniffi_ffi_result)
    @classmethod
    def new_with_proxy(cls, mnemonic: str,store: WalletStore,proxy_url: str) -> WalletRepository:
        """
        Create a new WalletRepository with proxy configuration.

        Construction restores locally persisted wallet state without making
        network requests to configured mints. The proxy is used by subsequent
        mint operations.
"""
        
        _UniffiFfiConverterString.check_lower(mnemonic)
        
        _UniffiFfiConverterTypeWalletStore.check_lower(store)
        
        _UniffiFfiConverterString.check_lower(proxy_url)
        _uniffi_lowered_args = (
            _UniffiFfiConverterString.lower(mnemonic),
            _UniffiFfiConverterTypeWalletStore.lower(store),
            _UniffiFfiConverterString.lower(proxy_url),
        )
        _uniffi_lift_return = _UniffiFfiConverterTypeWalletRepository.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeFfiError
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_cdk_ffi_fn_constructor_walletrepository_new_with_proxy,
            *_uniffi_lowered_args,
        )
        return cls._uniffi_make_instance(_uniffi_ffi_result)

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_cdk_ffi_fn_free_walletrepository, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_cdk_ffi_fn_clone_walletrepository, self._handle)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _uniffi_make_instance(cls, handle):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required handle.
        inst = cls.__new__(cls)
        inst._handle = handle
        return inst
