class _UniffiFfiConverterTypeWalletRepository:
    @staticmethod
    def lift(value: int) -> WalletRepository:
        return WalletRepository._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: WalletRepository):
        if not isinstance(value, WalletRepository):
            raise TypeError("Expected WalletRepository instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: WalletRepository) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> WalletRepository:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: WalletRepository, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))


