async def resolve_bip353_payment_instruction(wallet: Wallet,address: str,network: BitcoinNetwork) -> ParsedPaymentInstruction:
    """
    Resolve a BIP353 human-readable address into a parsed payment instruction.

    This uses the wallet's configured connector to resolve the address, then parses the resolved
    `bitcoin:` URI into a [`ParsedPaymentInstruction`] so callers can inspect the available
    methods before deciding how to pay or whether a BIP353 melt is possible.

    The `network` parameter controls which on-chain address prefixes are accepted
    in the resolved URI.
"""
    
    _UniffiFfiConverterTypeWallet.check_lower(wallet)
    
    _UniffiFfiConverterString.check_lower(address)
    
    _UniffiFfiConverterTypeBitcoinNetwork.check_lower(network)
    _uniffi_lowered_args = (
        _UniffiFfiConverterTypeWallet.lower(wallet),
        _UniffiFfiConverterString.lower(address),
        _UniffiFfiConverterTypeBitcoinNetwork.lower(network),
    )
    _uniffi_lift_return = _UniffiFfiConverterTypeParsedPaymentInstruction.lift
    _uniffi_error_converter = _UniffiFfiConverterTypeFfiError
    return await _uniffi_rust_call_async(
        _UniffiLib.uniffi_cdk_ffi_fn_func_resolve_bip353_payment_instruction(*_uniffi_lowered_args),
        _UniffiLib.ffi_cdk_ffi_rust_future_poll_rust_buffer,
        _UniffiLib.ffi_cdk_ffi_rust_future_complete_rust_buffer,
        _UniffiLib.ffi_cdk_ffi_rust_future_free_rust_buffer,
        _uniffi_lift_return,
        _uniffi_error_converter,
    )
